inline void drawPixelFace(U8G2 &oled, int idx, bool fullScreen = false) {
  idx = constrain(idx, 0, TOTAL_PIXEL_FACES - 1);
  const uint16_t* offs = fullScreen ? FULL_OFFSETS : HOME_OFFSETS;
  const uint16_t* lens = fullScreen ? FULL_LENGTHS : HOME_LENGTHS;
  const uint8_t* spans = fullScreen ? FULL_SPANS : HOME_SPANS;
  uint16_t off = pgm_read_word(&offs[idx]);
  uint16_t len = pgm_read_word(&lens[idx]);
  oled.setDrawColor(1);
  for (uint16_t i = 0; i < len; i++) {
    uint32_t b = (uint32_t)(off + i) * 3;
    oled.drawHLine(pgm_read_byte(&spans[b]), pgm_read_byte(&spans[b + 1]), pgm_read_byte(&spans[b + 2]));
  }
}
